import json
import re

def norm_stem(s):
    s = s.lower()
    s = re.sub(r'[\r\n\t]+', ' ', s)
    s = re.sub(r'[0-9]+', '#', s)
    s = re.sub(r'[.,/#!$%^&*;:{}=\-_`~()?"“”\']', '', s)
    s = re.sub(r'\s+', ' ', s)
    return s.strip()

cambridge_bank = []
seen_stems = set()

def add_q(qid, subj, grade, topic, question, options, correct_idx, explanation, hint, difficulty):
    stem = norm_stem(question)
    if stem in seen_stems:
        raise ValueError(f"Duplicate stem detected: {stem}")
    seen_stems.add(stem)
    cambridge_bank.append({
        "id": qid,
        "subject": subj,
        "curriculum": "cambridge",
        "grade": grade,
        "phase": f"Stage {grade}",
        "topic": topic,
        "question": question,
        "options": options,
        "correctIndex": correct_idx,
        "explanation": explanation,
        "hint": hint,
        "difficulty": difficulty
    })

